CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, nama_lengkap VARCHAR(100) NOT NULL, role ENUM('admin','pj_tahfidz','kepsek','ustadz') NOT NULL, no_hp VARCHAR(20), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE wali_santri (id INT AUTO_INCREMENT PRIMARY KEY, nama_bapak VARCHAR(100) NOT NULL, no_hp VARCHAR(20), alamat TEXT, kategori ENUM('reguler','tahsin_luar','askar') DEFAULT 'reguler', tempat_tahsin VARCHAR(255), ustadz_luar VARCHAR(100), status_aktif TINYINT DEFAULT 1, lanjut_tahsin TINYINT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE halaqoh (id INT AUTO_INCREMENT PRIMARY KEY, nama_halaqoh VARCHAR(100) NOT NULL, ustadz_id INT NOT NULL, FOREIGN KEY (ustadz_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE santri_detail (id INT AUTO_INCREMENT PRIMARY KEY, wali_santri_id INT NOT NULL, nama_anak VARCHAR(100) NOT NULL, kelas VARCHAR(20), FOREIGN KEY (wali_santri_id) REFERENCES wali_santri(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE halaqoh_members (id INT AUTO_INCREMENT PRIMARY KEY, halaqoh_id INT NOT NULL, wali_santri_id INT NOT NULL, FOREIGN KEY (halaqoh_id) REFERENCES halaqoh(id) ON DELETE CASCADE, FOREIGN KEY (wali_santri_id) REFERENCES wali_santri(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE presensi (id INT AUTO_INCREMENT PRIMARY KEY, halaqoh_id INT, wali_santri_id INT NOT NULL, tanggal DATE NOT NULL, status ENUM('H','S','I','A') NOT NULL, alasan TEXT, jenis_materi ENUM('Iqro','Al Quran'), jilid INT, nama_surat VARCHAR(100), halaman VARCHAR(20), hasil_talaqqi ENUM('Lulus','Ulang'), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, KEY idx_presensi_wali_tanggal(wali_santri_id,tanggal), KEY idx_presensi_halaqoh_tanggal(halaqoh_id,tanggal), FOREIGN KEY (halaqoh_id) REFERENCES halaqoh(id) ON DELETE SET NULL, FOREIGN KEY (wali_santri_id) REFERENCES wali_santri(id) ON DELETE CASCADE) ENGINE=InnoDB;
